insert into public.exercise_categories (id, slug, name, sort_order, is_demo) values
  ('7c3ba719-dfa1-591c-adc4-d3a3d77e0a5a', 'chest', 'Грудь', 1, true),
  ('eed9c5e0-7182-5e6d-af6f-b36d856c736c', 'back', 'Спина', 2, true),
  ('cbf91755-31b9-50e1-ac91-8869577348c1', 'legs', 'Ноги', 3, true),
  ('120e3a65-8ea4-52ce-a0fe-08ecf40f62d4', 'shoulders', 'Плечи', 4, true),
  ('b918d7ee-befa-5430-ae03-fc249c7f219c', 'biceps', 'Бицепс', 5, true),
