insert into public.exercises (id, category_id, name, description, technique, primary_muscles, equipment, difficulty, default_sets, default_reps, default_rest_sec, tips, mistakes, image_url, video_url, is_demo, is_published) values
  ('913e0102-b15c-5d3c-ac76-ae082829a671', '7c3ba719-dfa1-591c-adc4-d3a3d77e0a5a', 'Жим штанги лёжа', 'Базовое упражнение для развития силы и массы грудных мышц.', 'Лягте на скамью, сведите лопатки и упритесь стопами в пол. Возьмите гриф чуть шире плеч, опустите его к нижней части груди и выжмите вверх, не отрывая таз от скамьи.', array['Грудные', 'Трицепс', 'Передние дельты']::text[], 'barbell', 'intermediate', 4, 8, 120, array['Держите лопатки сведёнными весь подход', 'Опускайте гриф подконтрольно, 2–3 секунды']::text[], array['Отбив грифа от груди', 'Отрыв таза от скамьи', 'Слишком широко разведённые локти']::text[], null, null, true, true),
  ('1c69f839-ee82-5177-a42b-84609b6dc4bd', '7c3ba719-dfa1-591c-adc4-d3a3d77e0a5a', 'Отжимания от пола', 'Упражнение с собственным весом, подходит для дома.', 'Примите упор лёжа, ладони чуть шире плеч. Опускайтесь, сгибая локти под углом около 45° к корпусу, до касания грудью пола и вернитесь в исходное положение.', array['Грудные', 'Трицепс', 'Кор']::text[], 'none', 'beginner', 3, 15, 60, array['Держите корпус прямой линией', 'Если тяжело — выполняйте с колен']::text[], array['Провисание поясницы', 'Неполная амплитуда', 'Задранная голова']::text[], null, null, true, true),
  ('99e95162-f1a0-521b-a4cf-4febff830441', '7c3ba719-dfa1-591c-adc4-d3a3d77e0a5a', 'Разведение гантелей лёжа', 'Изолирующее упражнение на растяжение и сокращение грудных мышц.', 'Лёжа на скамье, поднимите гантели над грудью. Слегка согнув локти, разведите руки в стороны до комфортного растяжения и сведите обратно по дуге.', array['Грудные']::text[], 'dumbbells', 'intermediate', 3, 12, 75, array['Сохраняйте небольшой сгиб в локтях', 'Выбирайте умеренный вес']::text[], array['Слишком тяжёлые гантели', 'Выпрямление рук в локтях', 'Резкое движение в нижней точке']::text[], null, null, true, true),
  ('37bb484d-92c1-5596-a824-fe6d85729d7d', 'eed9c5e0-7182-5e6d-af6f-b36d856c736c', 'Подтягивания', 'Классическое упражнение для ширины спины.', 'Возьмитесь за перекладину хватом чуть шире плеч. Сведите лопатки и подтянитесь до уровня подбородка над перекладиной, затем плавно опуститесь.', array['Широчайшие', 'Бицепс', 'Ромбовидные']::text[], 'bar', 'intermediate', 4, 8, 120, array['Начинайте движение со сведения лопаток', 'Не раскачивайтесь']::text[], array['Рывки и раскачка', 'Неполное выпрямление рук внизу', 'Подъём плеч к ушам']::text[], null, null, true, true),
  ('65a8c0de-e0b9-516f-ae99-dafce48c41d4', 'eed9c5e0-7182-5e6d-af6f-b36d856c736c', 'Тяга штанги в наклоне', 'Базовая тяга для толщины спины.', 'Наклонитесь с прямой спиной до угла около 45°, колени слегка согнуты. Тяните гриф к поясу, сводя лопатки, и подконтрольно опускайте.', array['Широчайшие', 'Трапеции', 'Задние дельты']::text[], 'barbell', 'intermediate', 4, 10, 90, array['Спина остаётся прямой', 'Тяните локтями, а не кистями']::text[], array['Округление поясницы', 'Рывки корпусом', 'Слишком большой вес']::text[], null, null, true, true),
  ('b2ec5374-39dc-5e85-aaa7-a4dcf02b4f0a', 'eed9c5e0-7182-5e6d-af6f-b36d856c736c', 'Тяга верхнего блока', 'Упражнение в тренажёре, заменяет подтягивания для начинающих.', 'Сядьте в тренажёр, зафиксируйте бёдра. Тяните рукоять к верхней части груди, слегка прогнувшись, и плавно возвращайте вверх.', array['Широчайшие', 'Бицепс']::text[], 'machine', 'beginner', 3, 12, 75, array['Не отклоняйтесь назад слишком сильно', 'Опускайте плечи вниз перед тягой']::text[], array['Тяга за голову', 'Раскачка корпусом', 'Бросание веса вверх']::text[], null, null, true, true),
  ('368ba098-acb2-50e1-a5b1-f3959b333b84', 'cbf91755-31b9-50e1-ac91-8869577348c1', 'Приседания со штангой', 'Главное базовое упражнение для ног.', 'Расположите гриф на трапециях, стопы на ширине плеч. Опускайтесь, отводя таз назад, до параллели бёдер с полом и вставайте, сохраняя спину прямой.', array['Квадрицепсы', 'Ягодичные', 'Бицепс бедра']::text[], 'barbell', 'intermediate', 4, 8, 150, array['Колени направлены в сторону носков', 'Вес распределён на всю стопу']::text[], array['Сведение коленей внутрь', 'Отрыв пяток', 'Округление спины']::text[], null, null, true, true),
  ('d26c1141-d01d-526b-af56-5af49b3a839a', 'cbf91755-31b9-50e1-ac91-8869577348c1', 'Выпады', 'Упражнение для ног и баланса, выполняется с гантелями или без веса.', 'Сделайте шаг вперёд и опуститесь, пока оба колена не согнутся примерно до 90°. Оттолкнитесь передней ногой и вернитесь в исходное положение.', array['Квадрицепсы', 'Ягодичные']::text[], 'dumbbells', 'beginner', 3, 12, 75, array['Держите корпус вертикально', 'Шаг достаточно широкий']::text[], array['Колено уходит далеко за носок', 'Наклон корпуса вперёд', 'Слишком короткий шаг']::text[], null, null, true, true),
  ('44507cb2-8b5f-5d54-ad81-c9f764ec557d', 'cbf91755-31b9-50e1-ac91-8869577348c1', 'Ягодичный мост', 'Упражнение для ягодиц, подходит для дома.', 'Лёжа на спине, согните колени и поставьте стопы на пол. Поднимайте таз до прямой линии от плеч до коленей, задержитесь на секунду и опуститесь.', array['Ягодичные', 'Бицепс бедра']::text[], 'none', 'beginner', 3, 15, 60, array['Сжимайте ягодицы в верхней точке', 'Не переразгибайте поясницу']::text[], array['Толчок поясницей', 'Стопы слишком далеко от таза']::text[], null, null, true, true),
  ('b8aa9498-2b9d-5748-a2bb-0b91126dbc76', '120e3a65-8ea4-52ce-a0fe-08ecf40f62d4', 'Жим штанги стоя', 'Базовый жим для силы плечевого пояса.', 'Стоя, удерживайте гриф на уровне ключиц. Выжмите штангу над головой до выпрямления рук и плавно опустите обратно.', array['Дельты', 'Трицепс']::text[], 'barbell', 'intermediate', 4, 8, 120, array['Напрягите пресс и ягодицы', 'Гриф движется по вертикали']::text[], array['Сильный прогиб в пояснице', 'Помощь ногами', 'Локти уходят назад']::text[], null, null, true, true),
  ('a00877f9-e838-51a3-aa40-70d3b8d8453e', '120e3a65-8ea4-52ce-a0fe-08ecf40f62d4', 'Махи гантелями в стороны', 'Изолирующее упражнение для ширины плеч.', 'Стоя с гантелями по бокам, поднимайте руки через стороны до уровня плеч, слегка согнув локти, и плавно опускайте.', array['Средние дельты']::text[], 'dumbbells', 'beginner', 3, 15, 60, array['Локоть чуть выше кисти', 'Без раскачки корпусом']::text[], array['Слишком тяжёлые гантели', 'Подъём выше плеч', 'Рывки']::text[], null, null, true, true),
  ('644aee43-7d0c-50ed-a67b-0a34880a5ce6', '120e3a65-8ea4-52ce-a0fe-08ecf40f62d4', 'Отжимания «уголком»', 'Домашняя альтернатива жиму над головой.', 'Встаньте в упор лёжа и поднимите таз вверх, образуя перевёрнутую букву V. Сгибая руки, опускайте голову к полу между ладонями и выжимайте себя обратно.', array['Дельты', 'Трицепс']::text[], 'none', 'intermediate', 3, 10, 75, array['Смотрите на стопы', 'Локти направлены назад']::text[], array['Разведение локтей в стороны', 'Опускание таза']::text[], null, null, true, true),
  ('2e6bf8b1-7394-537b-aef2-9792f6a33c6e', 'b918d7ee-befa-5430-ae03-fc249c7f219c', 'Подъём штанги на бицепс', 'Основное упражнение для бицепса.', 'Стоя, возьмите гриф хватом снизу на ширине плеч. Сгибайте руки, не отводя локти от корпуса, и подконтрольно опускайте.', array['Бицепс']::text[], 'barbell', 'beginner', 3, 12, 60, array['Локти прижаты к корпусу', 'Опускайте медленно']::text[], array['Раскачка корпусом', 'Неполное разгибание']::text[], null, null, true, true),
  ('3402dc41-5ffa-5a3b-a5b0-409441b67d0f', 'b918d7ee-befa-5430-ae03-fc249c7f219c', 'Молотки с гантелями', 'Сгибания с нейтральным хватом для бицепса и предплечий.', 'Держите гантели ладонями друг к другу. Поочерёдно или одновременно сгибайте руки, сохраняя нейтральный хват.', array['Бицепс', 'Брахиалис']::text[], 'dumbbells', 'beginner', 3, 12, 60, array['Не разворачивайте кисти', 'Корпус неподвижен']::text[], array['Рывки', 'Локти уходят вперёд']::text[], null, null, true, true),
  ('28a43e01-0937-5b80-a7a8-f37bc8848400', 'b918d7ee-befa-5430-ae03-fc249c7f219c', 'Подтягивания обратным хватом', 'Подтягивания с акцентом на бицепс.', 'Возьмитесь за перекладину хватом снизу на ширине плеч. Подтянитесь до подбородка над перекладиной и плавно опуститесь.', array['Бицепс', 'Широчайшие']::text[], 'bar', 'intermediate', 3, 8, 90, array['Полная амплитуда', 'Без раскачки']::text[], array['Половинные повторения', 'Рывок ногами']::text[], null, null, true, true),
  ('a7ab4e6d-053a-5313-ae77-a261410fa2fb', 'b53eb261-3512-550e-ad14-5e10e7aa8666', 'Разгибания на блоке', 'Изолирующее упражнение для трицепса.', 'Стоя у верхнего блока, прижмите локти к корпусу и разгибайте руки вниз до полного выпрямления, затем плавно вернитесь.', array['Трицепс']::text[], 'machine', 'beginner', 3, 12, 60, array['Локти неподвижны', 'Задержка в нижней точке']::text[], array['Движение плечами', 'Наклон корпуса на рукоять']::text[], null, null, true, true),
  ('b4d66ff0-d0ee-5716-a727-09a722849aa8', 'b53eb261-3512-550e-ad14-5e10e7aa8666', 'Отжимания на брусьях', 'Базовое упражнение с собственным весом.', 'В упоре на брусьях опускайтесь, сгибая локти до угла около 90°, корпус держите вертикально для акцента на трицепс, затем выжмите себя вверх.', array['Трицепс', 'Грудные']::text[], 'bar', 'intermediate', 3, 10, 90, array['Плечи опущены', 'Не опускайтесь слишком глубоко']::text[], array['Чрезмерная глубина', 'Разведение локтей']::text[], null, null, true, true),
  ('47e3a52e-275a-52f2-a8a6-bf03864edcf8', 'b53eb261-3512-550e-ad14-5e10e7aa8666', 'Обратные отжимания от опоры', 'Домашнее упражнение для трицепса от стула или скамьи.', 'Упритесь ладонями в край опоры за спиной, ноги вытяните вперёд. Сгибайте локти до 90° и выжимайте себя вверх.', array['Трицепс']::text[], 'none', 'beginner', 3, 12, 60, array['Спина близко к опоре', 'Локти направлены назад']::text[], array['Плечи поднимаются к ушам', 'Слишком глубокое опускание']::text[], null, null, true, true),
  ('e6bc1f42-c83f-5ee0-a609-fd9bb4caa48b', '4ac6be33-91bf-5a97-a601-894bece74b2e', 'Планка', 'Статическое упражнение для мышц кора. Количество «повторений» — секунды удержания.', 'Упор на предплечья и носки, локти под плечами. Держите тело прямой линией, напрягая пресс и ягодицы.', array['Кор', 'Пресс']::text[], 'none', 'beginner', 3, 45, 45, array['Дышите ровно', 'Смотрите в пол']::text[], array['Провисание поясницы', 'Поднятый таз']::text[], null, null, true, true),
  ('89cc388e-67ea-5026-a599-dea0065b68c9', '4ac6be33-91bf-5a97-a601-894bece74b2e', 'Скручивания', 'Классическое упражнение для пресса.', 'Лёжа на спине с согнутыми коленями, поднимайте лопатки от пола за счёт сокращения пресса и плавно опускайтесь.', array['Прямая мышца живота']::text[], 'none', 'beginner', 3, 20, 45, array['Поясница прижата к полу', 'Не тяните голову руками']::text[], array['Рывок шеей', 'Подъём корпуса целиком']::text[], null, null, true, true),
  ('26fb21c0-8496-5f6d-a39d-e389e11d900f', '4ac6be33-91bf-5a97-a601-894bece74b2e', 'Подъём ног лёжа', 'Упражнение для нижней части пресса.', 'Лёжа на спине, поднимайте прямые ноги до вертикали и медленно опускайте, не касаясь пола.', array['Нижний пресс']::text[], 'none', 'intermediate', 3, 15, 60, array['Поясница прижата', 'Медленное опускание']::text[], array['Прогиб в пояснице', 'Мах ногами']::text[], null, null, true, true),
  ('762a5a79-7e58-54e0-a999-7e298ba971cb', 'a9d0f342-022e-525b-ab69-3b8b987ee798', 'Бег', 'Кардионагрузка в комфортном темпе. «Повторения» — минуты.', 'Бегите в темпе, при котором можете разговаривать. Приземляйтесь на среднюю часть стопы, держите корпус ровно.', array['Сердечно-сосудистая система', 'Ноги']::text[], 'none', 'beginner', 1, 20, 0, array['Начинайте с разминки', 'Контролируйте дыхание']::text[], array['Слишком быстрый старт', 'Приземление на пятку с прямой ногой']::text[], null, null, true, true),
  ('37f4d08f-95df-5d8c-ace6-be4428f47f48', 'a9d0f342-022e-525b-ab69-3b8b987ee798', 'Скакалка', 'Интенсивное кардио. «Повторения» — секунды работы.', 'Прыгайте на носках, вращая скакалку кистями. Локти прижаты к корпусу, прыжки невысокие.', array['Икры', 'Сердечно-сосудистая система']::text[], 'none', 'beginner', 5, 60, 30, array['Мягкое приземление', 'Вращение кистями']::text[], array['Высокие прыжки', 'Вращение всей рукой']::text[], null, null, true, true),
  ('059956e0-29c7-5157-ae16-61680ec2b9ce', 'a9d0f342-022e-525b-ab69-3b8b987ee798', 'Бёрпи', 'Комплексное упражнение высокой интенсивности.', 'Из положения стоя присядьте, поставьте ладони на пол, прыжком выйдите в упор лёжа, отожмитесь, прыжком подтяните ноги и выпрыгните вверх.', array['Всё тело']::text[], 'none', 'intermediate', 4, 12, 60, array['Держите ровный темп', 'Напрягайте кор в упоре']::text[], array['Провисание поясницы', 'Сбитое дыхание']::text[], null, null, true, true),
  ('609f60e0-36ba-57eb-a528-9a290a85f77d', 'ed200fc1-6dfa-576d-a78a-9beac762859d', 'Становая тяга', 'Базовое упражнение для всей задней цепи.', 'Подойдите к штанге, стопы под грифом. С прямой спиной возьмитесь за гриф и поднимите штангу, разгибая ноги и корпус одновременно. Опускайте подконтрольно.', array['Спина', 'Ягодичные', 'Бицепс бедра']::text[], 'barbell', 'advanced', 4, 6, 180, array['Гриф скользит вдоль ног', 'Лопатки над грифом на старте']::text[], array['Округление спины', 'Рывок со старта', 'Переразгибание вверху']::text[], null, null, true, true),
  ('bba98822-ee6f-57c5-a83a-0e3a62fd26f1', 'ed200fc1-6dfa-576d-a78a-9beac762859d', 'Махи гирей', 'Взрывное упражнение для всего тела.', 'Отведите гирю назад между ног с прямой спиной и мощным разгибанием таза выбросьте её до уровня груди.', array['Ягодичные', 'Спина', 'Плечи']::text[], 'kettlebell', 'intermediate', 4, 15, 75, array['Движение идёт от таза', 'Руки лишь направляют гирю']::text[], array['Подъём гири руками', 'Приседание вместо наклона']::text[], null, null, true, true),
  ('e9bee712-62b0-5ab0-acff-ea15268097b4', 'ed200fc1-6dfa-576d-a78a-9beac762859d', 'Альпинист', 'Динамическое упражнение в упоре лёжа. «Повторения» — секунды.', 'В упоре лёжа поочерёдно подтягивайте колени к груди в быстром темпе, удерживая таз на одной высоте.', array['Кор', 'Плечи', 'Ноги']::text[], 'none', 'beginner', 3, 30, 45, array['Плечи над кистями', 'Ровное дыхание']::text[], array['Поднятый таз', 'Провисание поясницы']::text[], null, null, true, true)
