  ('1bede798-f83a-5900-a780-644522a0306e', null, 'ed200fc1-6dfa-576d-a78a-9beac762859d', 'Фитнес-план: всё тело', 'Сбалансированная тренировка на все группы мышц для начинающих.', 'maintenance', 'beginner', 40, 'gym', 'strength', array['Ноги', 'Грудь', 'Спина', 'Кор']::text[], null, true, true),
