-- PULSE — демонстрационные данные (сгенерировано scripts/build-seed.mjs, не редактировать вручную).
-- Все строки помечены is_demo = true. Пользовательские результаты не создаются.
-- Повторный запуск безопасен: строки обновляются по первичному ключу.

on conflict (id) do update set slug = excluded.slug, name = excluded.name, sort_order = excluded.sort_order, is_demo = excluded.is_demo;

on conflict (id) do update set category_id = excluded.category_id, name = excluded.name, description = excluded.description, technique = excluded.technique, primary_muscles = excluded.primary_muscles, equipment = excluded.equipment, difficulty = excluded.difficulty, default_sets = excluded.default_sets, default_reps = excluded.default_reps, default_rest_sec = excluded.default_rest_sec, tips = excluded.tips, mistakes = excluded.mistakes, image_url = excluded.image_url, video_url = excluded.video_url, is_demo = excluded.is_demo, is_published = excluded.is_published;

on conflict (id) do update set owner_id = excluded.owner_id, category_id = excluded.category_id, name = excluded.name, description = excluded.description, goal_type = excluded.goal_type, difficulty = excluded.difficulty, duration_min = excluded.duration_min, location = excluded.location, workout_type = excluded.workout_type, target_muscles = excluded.target_muscles, image_url = excluded.image_url, is_demo = excluded.is_demo, is_published = excluded.is_published;

on conflict (id) do update set program_id = excluded.program_id, exercise_id = excluded.exercise_id, position = excluded.position, sets = excluded.sets, reps = excluded.reps, rest_sec = excluded.rest_sec;

on conflict (id) do update set owner_id = excluded.owner_id, name = excluded.name, category = excluded.category, kcal_100 = excluded.kcal_100, protein_100 = excluded.protein_100, fat_100 = excluded.fat_100, carbs_100 = excluded.carbs_100, serving_g = excluded.serving_g, image_url = excluded.image_url, external_source = excluded.external_source, external_id = excluded.external_id, is_demo = excluded.is_demo, is_published = excluded.is_published;

on conflict (id) do update set code = excluded.code, title = excluded.title, description = excluded.description, icon = excluded.icon, condition_type = excluded.condition_type, threshold = excluded.threshold, sort_order = excluded.sort_order, is_demo = excluded.is_demo;

on conflict (key) do update set value = excluded.value, is_public = excluded.is_public;
